#pragma once

template<typename T>
class Register {
public:
    T prev;
    T next;
    bool _stall;

    Register() : prev(static_cast<T>(0)), next(static_cast<T>(0)), _stall(false) {}

    explicit Register(const T &initial) : prev(initial), next(initial), _stall(false) {}

    T read() const {
        return prev;
    }

    T current() const {
        return next;
    }

    void write(const T &t) {
        next = t;
    }

    void tick() {
        if (!_stall) {
            prev = next;
        }
    }

    void stall(bool stall) {
        _stall = stall;
    }

    operator T() const {
        return read();
    }

    Register &operator=(const T &t) {
        write(t);
        return *this;
    }
};
